INSERT INTO `menu_categories` (`id`, `slug`, `name`, `description`, `sort_order`, `time_slot`, `is_active`, `created_at`, `updated_at`) VALUES
  (1, 'coffee-beverages', 'Coffee & Beverages', 'Specialty estate espresso, slow cold brews, and handcrafted signature coolers.', 0, 'all_day', 1, '2026-10-15 14:26:15', '2026-10-15 14:26:15'),
  (2, 'starters', 'Starters', 'Artisanal crostinis, fondue bowls, and crispy small bites for sharing.', 1, 'all_day', 1, '2026-10-15 14:26:15', '2026-10-15 14:26:15'),
  (3, 'mains', 'Mains', 'Hearty Continental plates, risottos, and wholesome European cafe bowls.', 2, 'all_day', 1, '2026-10-15 14:26:15', '2026-10-15 14:26:15'),
  (4, 'pizza-pasta', 'Pizza & Pasta', '48-hour fermented crust pizzas and slow-simmered artisanal pasta.', 3, 'all_day', 1, '2026-10-15 14:26:15', '2026-10-15 14:26:15'),
  (5, 'desserts', 'Desserts', 'Classic Italian dolci, molten tarts, and sweet table finishers.', 4, 'all_day', 1, '2026-10-15 14:26:15', '2026-10-15 14:26:15'),
  (6, 'test-artisanal', 'Artisanal Test Delicacies', NULL, 10, 'all_day', 1, '2026-10-17 18:57:12', '2026-10-17 18:57:12');
INSERT INTO `menu_items` (`id`, `category_id`, `name`, `slug`, `description`, `price_paise`, `is_veg`, `tag`, `image_url`, `is_available`, `sort_order`, `created_at`, `updated_at`) VALUES
  (1, 1, 'Cielo Citrus Cold Brew', 'cielo-citrus-cold-brew', 'Single-origin 18-hour cold brew infused with fresh orange zest and sparkling tonic.', 24000, 1, 'Signature', 'assets/images/dishes/orange-espresso-tonic.webp', 1, 0, '2026-10-15 14:26:15', '2026-10-15 14:26:15'),
  (2, 1, 'Sunset Spritzer Mocktail', 'sunset-spritzer-mocktail', 'Vibrant layered mocktail featuring pomegranate reduction, citrus cordial, and crushed fresh mint.', 22000, 1, 'Bestseller', 'assets/images/dishes/sunset-mocktail.webp', 1, 1, '2026-10-15 14:26:15', '2026-10-15 14:26:15'),
  (3, 1, 'Artisan Caramel Flat White', 'artisan-caramel-flat-white', 'Double ristretto shot with velvety micro-foam, madagascar vanilla bean, and salted caramel drizzle.', 21000, 1, 'Barista Pick', 'assets/images/cafe/hero-table.webp', 1, 2, '2026-10-15 14:26:15', '2026-10-15 14:26:15'),
  (4, 1, 'Iced Shakerato Lemonade', 'iced-shakerato-lemonade', 'Vigorously shaken dark roast espresso over crushed ice with organic Sicilian lemon syrup.', 23000, 1, 'Refreshing', 'assets/images/cafe/interior-atmosphere.webp', 1, 3, '2026-10-15 14:26:15', '2026-10-15 14:26:15'),
  (5, 1, 'Spanish Cortado & Dark Mocha', 'spanish-cortado-dark-mocha', 'Balanced 1:1 espresso and silky textured milk with melted 70% dark Belgian cocoa.', 22000, 1, 'Classic', 'assets/images/cafe/all-day-spread.webp', 1, 4, '2026-10-15 14:26:15', '2026-10-15 14:26:15'),
  (6, 2, 'Artisanal Burrata Bruschetta', 'artisanal-burrata-bruschetta', 'Charred sourdough baguette topped with ripe plum tomatoes, creamy stracciatella, Kalamata olives, and fresh basil.', 29000, 1, 'Must Try', 'assets/images/dishes/bruschetta-burrata.webp', 1, 5, '2026-10-15 14:26:15', '2026-10-15 14:26:15'),
  (7, 2, 'Warm Cheese Fondue Platter', 'warm-cheese-fondue-platter', 'Melted Gruyère and Emmental dip served with seasoned pita triangles, roasted broccoli florets, and herb croutons.', 38000, 1, 'Chef Special', 'assets/images/dishes/cheese-fondue-platter.webp', 1, 6, '2026-10-15 14:26:15', '2026-10-15 14:26:15'),
  (8, 2, 'Crispy Peri-Peri Truffle Fries', 'crispy-peri-peri-truffle-fries', 'Hand-cut golden potato batons tossed in house spice rub, micro-greens, and served with garlic aioli.', 21000, 1, 'Crowd Favorite', 'assets/images/dishes/peri-peri-fries.webp', 1, 7, '2026-10-15 14:26:15', '2026-10-15 14:26:15'),
  (9, 2, 'Classic Tomato Basil Crostini', 'classic-tomato-basil-crostini', 'Toasted garlic sourdough slices crowned with slow-roasted cherry tomatoes, cold-pressed olive oil, and lime mist.', 26000, 1, 'Italian Classic', 'assets/images/dishes/bruschetta-carved.webp', 1, 8, '2026-10-15 14:26:15', '2026-10-15 14:26:15'),
  (10, 2, 'Charred Cottage Cheese Skewers', 'charred-cottage-cheese-skewers', 'Soft Malai paneer cubes cured in sun-dried tomato pesto and grilled over open flame.', 32000, 1, 'Tandoor Twist', 'assets/images/cafe/hero-table.webp', 1, 9, '2026-10-15 14:26:15', '2026-10-15 14:26:15'),
  (11, 3, 'Wild Mushroom Risotto Parmigiano', 'wild-mushroom-risotto-parmigiano', 'Slow-stirred Arborio rice in Porcini mushroom broth, white wine reduction, finished with aged 24-month Parmigiano.', 42000, 1, 'House Specialty', 'assets/images/cafe/all-day-spread.webp', 1, 10, '2026-10-15 14:26:15', '2026-10-15 14:26:15'),
  (12, 3, 'Rustic Tuscan Vegetable Stufato', 'rustic-tuscan-vegetable-stufato', 'Slow-braised zucchini, bell peppers, baby aubergine, and chickpeas in rich pomodoro sauce with garlic sourdough.', 39000, 1, 'Comfort Food', 'assets/images/cafe/hero-table.webp', 1, 11, '2026-10-15 14:26:15', '2026-10-15 14:26:15'),
  (13, 3, 'Creamy Polenta with Truffle Glaze', 'creamy-polenta-with-truffle-glaze', 'Golden sweetcorn polenta cooked with butter and mascarpone, topped with charred greens and balsamic drizzle.', 37000, 1, 'Gluten-Free', 'assets/images/dishes/bruschetta-artisan.webp', 1, 12, '2026-10-15 14:26:15', '2026-10-15 14:26:15'),
  (14, 3, 'Cielo Mediterranean Mezze Bowl', 'cielo-mediterranean-mezze-bowl', 'Warm falafel patties, beetroot hummus, herb tabbouleh, marinated olives, and toasted pita crisps.', 36000, 1, 'All-Day Bowl', 'assets/images/dishes/cheese-fondue-platter.webp', 1, 13, '2026-10-15 14:26:15', '2026-10-15 14:26:15'),
  (15, 4, 'Spaghetti Pomodoro E Basilico', 'spaghetti-pomodoro-e-basilico', 'Bronze-cut spaghetti twirled in sweet San Marzano tomato sauce, fresh cherry tomatoes, Kalamata olives, and sweet basil.', 36000, 1, 'Signature', 'assets/images/cafe/menu-cover-spaghetti.webp', 1, 14, '2026-10-15 14:26:15', '2026-10-15 14:26:15'),
  (16, 4, 'Genovese Pesto & Sundried Tomato Pizza', 'genovese-pesto-sundried-tomato-pizza', 'Hand-stretched 48-hr crust, basil-pinenut pesto base, confit tomatoes, sun-dried tomatoes, and Fior di Latte mozzarella.', 46000, 1, 'Chef Special', 'assets/images/dishes/pesto-pizza.webp', 1, 15, '2026-10-15 14:26:15', '2026-10-15 14:26:15'),
  (17, 4, 'Cielo Quattro Formaggi Deluxe', 'cielo-quattro-formaggi-deluxe', 'Creamy Mozzarella, Gorgonzola, smoked Scamorza, and shaved Parmesan with charred garlic and oregano.', 49000, 1, 'Cheese Lover', 'assets/images/cafe/all-day-spread.webp', 1, 16, '2026-10-15 14:26:15', '2026-10-15 14:26:15'),
  (18, 4, 'Truffle Penne Al Funghi', 'truffle-penne-al-funghi', 'Al dente penne rigate enveloped in rich white mushroom velouté, black truffle oil, and cracked pink peppercorn.', 39000, 1, 'Bestseller', 'assets/images/cafe/hero-table.webp', 1, 17, '2026-10-15 14:26:15', '2026-10-15 14:26:15'),
  (19, 4, 'Fire-Roasted Bell Pepper Pizza', 'fire-roasted-bell-pepper-pizza', 'Spicy arrabbiata sauce base, chargrilled sweet peppers, yellow zucchini, jalapeños, and fresh bocconcini.', 44000, 1, 'Spicy', 'assets/images/cafe/all-day-spread.webp', 1, 18, '2026-10-15 14:26:15', '2026-10-15 14:26:15'),
  (20, 5, 'Classic Venetian Tiramisu', 'classic-venetian-tiramisu', 'Espresso-soaked Savoiardi ladyfingers layered with whipped mascarpone cream and dusted with raw cocoa powder.', 28000, 1, 'Signature', 'assets/images/cafe/menu-cover-spaghetti.webp', 1, 19, '2026-10-15 14:26:15', '2026-10-15 14:26:15'),
  (21, 5, 'Warm Belgian Molten Cake', 'warm-belgian-molten-cake', 'Gooey chocolate center served warm with Madagascan vanilla bean gelato and dark chocolate crumble.', 31000, 1, 'Bestseller', 'assets/images/cafe/hero-table.webp', 1, 20, '2026-10-15 14:26:15', '2026-10-15 14:26:15'),
  (22, 5, 'Baked New York Blueberry Cheesecake', 'baked-new-york-blueberry-cheesecake', 'Creamy Philadelphia cheesecake on a crunchy graham crust crowned with slow-reduced wild berry compote.', 29000, 1, 'Chef Special', 'assets/images/dishes/bruschetta-carved.webp', 1, 21, '2026-10-15 14:26:15', '2026-10-15 14:26:15'),
  (23, 5, 'Espresso Affogato Al Caffe', 'espresso-affogato-al-caffe', 'Two scoops of artisanal vanilla bean gelato drowned in a freshly pulled double shot of Cielo espresso.', 21000, 1, 'Classic', 'assets/images/dishes/orange-espresso-tonic.webp', 1, 22, '2026-10-15 14:26:15', '2026-10-15 14:26:15'),
  (24, 6, 'Artisanal Test Sourdough Pizza 6ad377b11c5c1', 'art-pizza-6ad377b11c5c2', 'Stone-baked rustic crust', 49500, 1, NULL, NULL, 1, 1, '2026-10-17 18:57:13', '2026-10-17 18:57:13'),
